 class Icon extends View{String kind;Paint p=new Paint(3);int color;Icon(String k,int c){super(MainActivity.this);kind=k;color=c;}protected void onDraw(Canvas c){c.save();c.scale(getWidth()/32f,getHeight()/32f);p.setColor(color);p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(2.4f);p.setStrokeCap(Paint.Cap.ROUND);if(kind.equals("route")){c.drawCircle(8,24,4,p);c.drawCircle(24,8,4,p);Path path=new Path();path.moveTo(8,20);path.lineTo(8,12);path.quadTo(8,8,14,8);path.lineTo(20,8);c.drawPath(path,p);}else if(kind.equals("compare")){c.drawLine(6,9,26,9,p);c.drawLine(6,23,26,23,p);c.drawLine(22,5,26,9,p);c.drawLine(22,13,26,9,p);c.drawLine(10,19,6,23,p);c.drawLine(10,27,6,23,p);}else for(int i=0;i<3;i++){int y=7+i*9;c.drawLine(4,y,28,y,p);c.drawCircle(i==1?12:21,y,3,p);}c.restore();}}
